1	package com.example.starter.blend;
2	
3	import com.example.starter.blend.BlendCalculator.ComponentSnapshot;
4	import com.example.starter.blend.BlendCalculator.Judgment;
5	import com.example.starter.blend.BlendCalculator.SpecLimits;
6	import com.example.starter.blend.BlendDtos.BatchView;
7	import com.example.starter.blend.BlendDtos.ComponentAmount;
8	import com.example.starter.blend.BlendDtos.CreateOrderRequest;
9	import com.example.starter.blend.BlendDtos.Metrics;
10	import com.example.starter.blend.BlendDtos.OrderDetail;
11	import com.example.starter.blend.BlendDtos.OrderResponse;
12	import com.example.starter.blend.BlendDtos.ReblendRequest;
13	import com.example.starter.blend.BlendDtos.ReblendResponse;
14	import com.example.starter.blend.BlendDtos.ReleaseRequest;
15	import com.example.starter.blend.BlendDtos.ReleaseResponse;
16	import com.example.starter.blend.BlendDtos.SampleRequest;
17	import com.example.starter.blend.BlendDtos.SampleResponse;
18	import com.example.starter.blend.BlendDtos.SampleView;
19	import com.example.starter.blend.BlendRepository.BatchComponentRow;
20	import com.example.starter.blend.BlendRepository.BatchRow;
21	import com.example.starter.blend.BlendRepository.ComponentTankRow;
22	import com.example.starter.blend.BlendRepository.OrderRow;
23	import com.example.starter.blend.BlendRepository.SpecRow;
24	import org.springframework.context.annotation.Lazy;
25	import org.springframework.dao.DuplicateKeyException;
26	import org.springframework.stereotype.Service;
27	import org.springframework.transaction.annotation.Transactional;
28	
29	import java.math.BigDecimal;
30	import java.time.Clock;
31	import java.time.LocalDateTime;
32	import java.time.format.DateTimeFormatter;
33	import java.util.ArrayList;
34	import java.util.Comparator;
35	import java.util.List;
36	import java.util.stream.Collectors;
37	
38	/**
39	 * 调合业务服务：配方下达、组分切罐、在线调和、化验判定、放行/返调。
40	 * 公开方法负责幂等包装，内部 doXxx 方法在单一事务内完成状态变更与库存扣减。
41	 */
42	@Service
43	public class BlendService {
44	
45	    /** 调合单状态：执行中。 */
46	    public static final String ORDER_EXECUTING = "EXECUTING";
47	    /** 调合单状态：已放行封账（终态）。 */
48	    public static final String ORDER_RELEASED = "RELEASED";
49	    /** 调合单状态：不合格品（终态）。 */
50	    public static final String ORDER_UNQUALIFIED = "UNQUALIFIED";
51	
52	    /** 批次状态：调和化验中。 */
53	    public static final String BATCH_OPEN = "OPEN";
54	    /** 批次状态：首样合格，待次样。 */
55	    public static final String BATCH_SAMPLE1_PASSED = "SAMPLE1_PASSED";
56	    /** 批次状态：首样不合格，允许返调一次。 */
57	    public static final String BATCH_SAMPLE1_FAILED = "SAMPLE1_FAILED";
58	    /** 批次状态：双采样均合格。 */
59	    public static final String BATCH_PASSED = "PASSED";
60	    /** 批次状态：判定不合格。 */
61	    public static final String BATCH_FAILED = "FAILED";
62	
63	    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
64	
65	    private final BlendRepository repository;
66	    private final BlendCalculator calculator;
67	    private final IdempotencyExecutor idempotency;
68	    private final Clock clock;
69	    private final BlendService self;
70	
71	    public BlendService(BlendRepository repository, BlendCalculator calculator,
72	                        IdempotencyExecutor idempotency, Clock clock, @Lazy BlendService self) {
73	        this.repository = repository;
74	        this.calculator = calculator;
75	        this.idempotency = idempotency;
76	        this.clock = clock;
77	        this.self = self;
78	    }
79	
80	    /**
81	     * 下达调合单：requestId 幂等；校验罐余量，组分切罐与库存扣减在同一事务内完成；
82	     * 任一组分不足则整单不下达且库存无变动；同一调合罐同时刻只允许一张执行中调合单。
83	     */
84	    public OrderResponse createOrder(CreateOrderRequest request) {
85	        String fingerprint = idempotency.fingerprint(request.requestId(), "CREATE_ORDER",
86	                request.productCode(), request.blendTankId(), canonicalComponents(request.components()));
87	        return idempotency.execute("CREATE_ORDER", request.requestId(), fingerprint,
88	                OrderResponse.class, () -> self.doCreateOrder(request));
89	    }
90	
91	    /**
92	     * 提交化验：requestId 幂等；双采样点均合格方可放行；首样不合格允许返调一次；
93	     * 封账后迟到数据只记迟到事件，不改判定结论。
94	     */
95	    public SampleResponse submitSample(long orderId, SampleRequest request) {
96	        String fingerprint = idempotency.fingerprint(request.requestId(), "SAMPLE",
97	                orderId, request.samplePoint());
98	        return idempotency.execute("SAMPLE", request.requestId(), fingerprint,
99	                SampleResponse.class, () -> self.doSubmitSample(orderId, request));
100	    }
101	
102	    /**
103	     * 返调：requestId 幂等；仅首样不合格后允许一次，生成新批次并引用原批次，重走双采样判定。
104	     */
105	    public ReblendResponse reblend(long orderId, ReblendRequest request) {
106	        String fingerprint = idempotency.fingerprint(request.requestId(), "REBLEND",
107	                orderId, canonicalComponents(request.components()));
108	        return idempotency.execute("REBLEND", request.requestId(), fingerprint,
109	                ReblendResponse.class, () -> self.doReblend(orderId, request));
110	    }
111	
112	    /**
113	     * 放行封账：requestId 幂等；终态，重复封账返回幂等成功。
114	     */
115	    public ReleaseResponse release(long orderId, ReleaseRequest request) {
116	        String fingerprint = idempotency.fingerprint(request.requestId(), "RELEASE", orderId);
117	        return idempotency.execute("RELEASE", request.requestId(), fingerprint,
118	                ReleaseResponse.class, () -> self.doRelease(orderId, request));
119	    }
120	
121	    /**
122	     * 查询调合单详情：指标、卡边率与批次链均由组分快照复算，重复查询结果稳定。
123	     */
124	    @Transactional(readOnly = true)
125	    public OrderDetail getOrder(long orderId) {
126	        OrderRow order = repository.findOrder(orderId)
127	                .orElseThrow(() -> BlendException.notFound("调合单不存在: " + orderId));
128	        List<BatchRow> batches = repository.findBatches(orderId);
129	        List<BatchView> batchViews = new ArrayList<>();
130	        for (BatchRow batch : batches) {
131	            List<SampleView> samples = repository.findSamples(batch.id()).stream()
132	                    .map(s -> new SampleView(s.id(), s.samplePoint(), s.qualified(),
133	                            new Metrics(s.octane(), s.sulfur(), s.vaporPressure()),
134	                            splitHints(s.hints())))
135	                    .toList();
136	            batchViews.add(new BatchView(batch.id(), batch.seq(), batch.originBatchId(), batch.status(), samples));
137	        }
138	        BatchRow latest = batches.get(batches.size() - 1);
139	        Metrics metrics = computeBatchMetrics(latest.id());
140	        Judgment judgment = judgeOrder(order.productCode(), metrics);
141	        return new OrderDetail(order.id(), order.orderNo(), order.productCode(), order.blendTankId(),
142	                order.status(), order.totalVolume(), order.reblendCount(), metrics, judgment.marginHints(),
143	                batchViews, repository.findLateEvents(orderId));
144	    }
145	
146	    /**
147	     * 配方下达事务体：校验、切罐、扣量、占锁同事务，任一步失败整体回滚。
148	     */
149	    @Transactional
150	    public OrderResponse doCreateOrder(CreateOrderRequest request) {
151	        SpecRow spec = repository.findSpec(request.productCode())
152	                .orElseThrow(() -> BlendException.notFound("成品规格不存在: " + request.productCode()));
153	        if (!repository.blendTankExists(request.blendTankId())) {
154	            throw BlendException.notFound("调合罐不存在: " + request.blendTankId());
155	        }
156	        LocalDateTime now = LocalDateTime.now(clock);
157	        // 先逐罐校验余量（行锁），任一组分不足则整单拒绝，不产生任何库存变动
158	        List<ComponentTankRow> tanks = new ArrayList<>();
159	        for (ComponentAmount component : request.components()) {
160	            ComponentTankRow tank = repository.findComponentTankForUpdate(component.tankId())
161	                    .orElseThrow(() -> BlendException.notFound("组分罐不存在: " + component.tankId()));
162	            if (tank.remainingVolume().compareTo(component.volume()) < 0) {
163	                throw BlendException.unprocessable("组分罐" + tank.code() + "余量不足，整单不予下达，库存无变动");
164	            }
165	            tanks.add(tank);
166	        }
167	        BigDecimal totalVolume = request.components().stream()
168	                .map(ComponentAmount::volume)
169	                .reduce(BigDecimal.ZERO, BigDecimal::add);
170	        long orderId = repository.insertOrder("TMP-" + request.requestId(), request.requestId(),
171	                request.productCode(), request.blendTankId(), ORDER_EXECUTING, totalVolume, now);
172	        String orderNo = String.format("BO%08d", orderId);
173	        repository.updateOrderNo(orderId, orderNo);
174	        // 同一调合罐同时刻只允许一张执行中调合单
175	        try {
176	            repository.acquireTankLock(request.blendTankId(), orderId, now);
177	        } catch (DuplicateKeyException e) {
178	            throw BlendException.conflict("调合罐" + request.blendTankId() + "存在执行中调合单，本次下达被拒绝");
179	        }
180	        long batchId = repository.insertBatch(orderId, 1, null, BATCH_OPEN, now);
181	        List<ComponentSnapshot> snapshots = new ArrayList<>();
182	        for (int i = 0; i < tanks.size(); i++) {
183	            ComponentTankRow tank = tanks.get(i);
184	            BigDecimal volume = request.components().get(i).volume();
185	            repository.insertBatchComponent(batchId, tank.id(), tank.code(), volume,
186	                    tank.octane(), tank.sulfur(), tank.vaporPressure());
187	            if (repository.deductComponentVolume(tank.id(), volume) != 1) {
188	                throw BlendException.unprocessable("组分罐" + tank.code() + "余量不足，整单不予下达，库存无变动");
189	            }
190	            snapshots.add(new ComponentSnapshot(volume, tank.octane(), tank.sulfur(), tank.vaporPressure()));
191	        }
192	        Metrics metrics = calculator.computeMetrics(snapshots);
193	        Judgment judgment = calculator.judge(metrics, toLimits(spec));
194	        return new OrderResponse(orderId, orderNo, ORDER_EXECUTING, batchId, totalVolume,
195	                metrics, judgment.marginHints());
196	    }
197	
198	    /**
199	     * 化验提交事务体。
200	     */
201	    @Transactional
202	    public SampleResponse doSubmitSample(long orderId, SampleRequest request) {
203	        OrderRow order = repository.findOrder(orderId)
204	                .orElseThrow(() -> BlendException.notFound("调合单不存在: " + orderId));
205	        BatchRow batch = repository.findLatestBatch(orderId)
206	                .orElseThrow(() -> BlendException.conflict("调合单无调合批次"));
207	        if (ORDER_RELEASED.equals(order.status())) {
208	            // 封账终态：迟到化验数据只记迟到事件，不改判定结论
209	            repository.insertLateEvent(orderId, batch.id(), request.samplePoint(), request.requestId(),
210	                    "封账后迟到化验数据（采样点" + request.samplePoint() + "），仅记录不改判定结论",
211	                    LocalDateTime.now(clock));
212	            return new SampleResponse(null, batch.id(), request.samplePoint(), false,
213	                    computeBatchMetrics(batch.id()), List.of(), ORDER_RELEASED, true);
214	        }
215	        if (ORDER_UNQUALIFIED.equals(order.status())) {
216	            throw BlendException.conflict("调合单已转不合格品终态，不再接受化验数据");
217	        }
218	        return switch (request.samplePoint()) {
219	            case 1 -> submitFirstSample(order, batch, request.requestId());
220	            case 2 -> submitSecondSample(order, batch, request.requestId());
221	            default -> throw BlendException.conflict("采样点仅支持1或2");
222	        };
223	    }
224	
225	    /**
226	     * 返调事务体：新批次引用原批次，追加组分切罐扣量与状态变更同事务。
227	     */
228	    @Transactional
229	    public ReblendResponse doReblend(long orderId, ReblendRequest request) {
230	        OrderRow order = repository.findOrder(orderId)
231	                .orElseThrow(() -> BlendException.notFound("调合单不存在: " + orderId));
232	        if (!ORDER_EXECUTING.equals(order.status())) {
233	            throw BlendException.conflict("调合单状态为" + order.status() + "，不允许返调");
234	        }
235	        if (order.reblendCount() > 0) {
236	            throw BlendException.conflict("返调仅限一次，本单已返调过");
237	        }
238	        BatchRow origin = repository.findLatestBatch(orderId)
239	                .orElseThrow(() -> BlendException.conflict("调合单无调合批次"));
240	        if (!BATCH_SAMPLE1_FAILED.equals(origin.status())) {
241	            throw BlendException.conflict("仅首样不合格后允许返调");
242	        }
243	        LocalDateTime now = LocalDateTime.now(clock);
244	        List<ComponentTankRow> tanks = new ArrayList<>();
245	        for (ComponentAmount component : request.components()) {
246	            ComponentTankRow tank = repository.findComponentTankForUpdate(component.tankId())
247	                    .orElseThrow(() -> BlendException.notFound("组分罐不存在: " + component.tankId()));
248	            if (tank.remainingVolume().compareTo(component.volume()) < 0) {
249	                throw BlendException.unprocessable("组分罐" + tank.code() + "余量不足，返调不予执行，库存无变动");
250	            }
251	            tanks.add(tank);
252	        }
253	        long newBatchId = repository.insertBatch(orderId, origin.seq() + 1, origin.id(), BATCH_OPEN, now);
254	        // 新批次继承原批次全部组分（罐内油仍留存），再追加返调组分
255	        List<ComponentSnapshot> snapshots = new ArrayList<>();
256	        for (BatchComponentRow old : repository.findBatchComponents(origin.id())) {
257	            repository.insertBatchComponent(newBatchId, old.tankId(), old.tankCode(), old.volume(),
258	                    old.octane(), old.sulfur(), old.vaporPressure());
259	            snapshots.add(new ComponentSnapshot(old.volume(), old.octane(), old.sulfur(), old.vaporPressure()));
260	        }
261	        BigDecimal addedVolume = BigDecimal.ZERO;
262	        for (int i = 0; i < tanks.size(); i++) {
263	            ComponentTankRow tank = tanks.get(i);
264	            BigDecimal volume = request.components().get(i).volume();
265	            repository.insertBatchComponent(newBatchId, tank.id(), tank.code(), volume,
266	                    tank.octane(), tank.sulfur(), tank.vaporPressure());
267	            if (repository.deductComponentVolume(tank.id(), volume) != 1) {
268	                throw BlendException.unprocessable("组分罐" + tank.code() + "余量不足，返调不予执行，库存无变动");
269	            }
270	            snapshots.add(new ComponentSnapshot(volume, tank.octane(), tank.sulfur(), tank.vaporPressure()));
271	            addedVolume = addedVolume.add(volume);
272	        }
273	        repository.markReblended(orderId, addedVolume);
274	        Metrics metrics = calculator.computeMetrics(snapshots);
275	        SpecRow spec = repository.findSpec(order.productCode())
276	                .orElseThrow(() -> BlendException.notFound("成品规格不存在: " + order.productCode()));
277	        Judgment judgment = calculator.judge(metrics, toLimits(spec));
278	        return new ReblendResponse(orderId, newBatchId, origin.id(), origin.seq() + 1,
279	                metrics, judgment.marginHints(), ORDER_EXECUTING);
280	    }
281	
282	    /**
283	     * 放行封账事务体：终态；重复封账返回幂等成功。
284	     */
285	    @Transactional
286	    public ReleaseResponse doRelease(long orderId, ReleaseRequest request) {
287	        OrderRow order = repository.findOrder(orderId)
288	                .orElseThrow(() -> BlendException.notFound("调合单不存在: " + orderId));
289	        if (ORDER_RELEASED.equals(order.status())) {
290	            return new ReleaseResponse(orderId, ORDER_RELEASED, formatTime(order.releasedAt()));
291	        }
292	        if (ORDER_UNQUALIFIED.equals(order.status())) {
293	            throw BlendException.conflict("调合单已转不合格品终态，不能放行");
294	        }
295	        BatchRow batch = repository.findLatestBatch(orderId)
296	                .orElseThrow(() -> BlendException.conflict("调合单无调合批次"));
297	        if (!BATCH_PASSED.equals(batch.status())) {
298	            throw BlendException.conflict("双采样未全部合格，不能放行封账");
299	        }
300	        LocalDateTime now = LocalDateTime.now(clock);
301	        repository.updateOrderStatus(orderId, ORDER_RELEASED, now);
302	        repository.releaseTankLock(order.blendTankId());
303	        return new ReleaseResponse(orderId, ORDER_RELEASED, formatTime(now));
304	    }
305	
306	    private SampleResponse submitFirstSample(OrderRow order, BatchRow batch, String requestId) {
307	        if (BATCH_SAMPLE1_PASSED.equals(batch.status())) {
308	            throw BlendException.conflict("首样已提交且合格，请提交次样");
309	        }
310	        if (BATCH_SAMPLE1_FAILED.equals(batch.status())) {
311	            throw BlendException.conflict("首样已判定不合格，请执行返调");
312	        }
313	        if (!BATCH_OPEN.equals(batch.status())) {
314	            throw BlendException.conflict("批次状态为" + batch.status() + "，不接受首样");
315	        }
316	        Metrics metrics = computeBatchMetrics(batch.id());
317	        Judgment judgment = judgeOrder(order.productCode(), metrics);
318	        long sampleId = insertSampleGuarded(batch.id(), 1, requestId, metrics, judgment);
319	        String orderStatus = order.status();
320	        if (judgment.qualified()) {
321	            repository.updateBatchStatus(batch.id(), BATCH_SAMPLE1_PASSED);
322	        } else if (order.reblendCount() == 0) {
323	            repository.updateBatchStatus(batch.id(), BATCH_SAMPLE1_FAILED);
324	        } else {
325	            // 返调批次首样仍不合格：整罐转不合格品终态，不得再次返调
326	            repository.updateBatchStatus(batch.id(), BATCH_FAILED);
327	            repository.updateOrderStatus(order.id(), ORDER_UNQUALIFIED, null);
328	            repository.releaseTankLock(order.blendTankId());
329	            orderStatus = ORDER_UNQUALIFIED;
330	        }
331	        return new SampleResponse(sampleId, batch.id(), 1, judgment.qualified(),
332	                metrics, judgment.marginHints(), orderStatus, false);
333	    }
334	
335	    private SampleResponse submitSecondSample(OrderRow order, BatchRow batch, String requestId) {
336	        if (!BATCH_SAMPLE1_PASSED.equals(batch.status())) {
337	            throw BlendException.conflict("首样未合格，不能提交次样");
338	        }
339	        Metrics metrics = computeBatchMetrics(batch.id());
340	        Judgment judgment = judgeOrder(order.productCode(), metrics);
341	        long sampleId = insertSampleGuarded(batch.id(), 2, requestId, metrics, judgment);
342	        String orderStatus = order.status();
343	        if (judgment.qualified()) {
344	            repository.updateBatchStatus(batch.id(), BATCH_PASSED);
345	        } else {
346	            // 次样不合格不允许返调，整罐转不合格品终态
347	            repository.updateBatchStatus(batch.id(), BATCH_FAILED);
348	            repository.updateOrderStatus(order.id(), ORDER_UNQUALIFIED, null);
349	            repository.releaseTankLock(order.blendTankId());
350	            orderStatus = ORDER_UNQUALIFIED;
351	        }
352	        return new SampleResponse(sampleId, batch.id(), 2, judgment.qualified(),
353	                metrics, judgment.marginHints(), orderStatus, false);
354	    }
355	
356	    private long insertSampleGuarded(long batchId, int samplePoint, String requestId,
357	                                     Metrics metrics, Judgment judgment) {
358	        try {
359	            return repository.insertSample(batchId, samplePoint, requestId,
360	                    metrics.octane(), metrics.sulfur(), metrics.vaporPressure(),
361	                    judgment.qualified(), String.join(";", judgment.marginHints()),
362	                    LocalDateTime.now(clock));
363	        } catch (DuplicateKeyException e) {
364	            throw BlendException.conflict("采样点" + samplePoint + "已提交化验结果");
365	        }
366	    }
367	
368	    private Metrics computeBatchMetrics(long batchId) {
369	        List<ComponentSnapshot> snapshots = repository.findBatchComponents(batchId).stream()
370	                .map(c -> new ComponentSnapshot(c.volume(), c.octane(), c.sulfur(), c.vaporPressure()))
371	                .toList();
372	        return calculator.computeMetrics(snapshots);
373	    }
374	
375	    private Judgment judgeOrder(String productCode, Metrics metrics) {
376	        SpecRow spec = repository.findSpec(productCode)
377	                .orElseThrow(() -> BlendException.notFound("成品规格不存在: " + productCode));
378	        return calculator.judge(metrics, toLimits(spec));
379	    }
380	
