318	    }
319	
320	    /**
321	     * 插入幂等占位记录（处理中）。唯一键冲突时抛出 DuplicateKeyException。
322	     */
323	    public void insertIdempotency(String requestId, String endpoint, String fingerprint,
324	                                  LocalDateTime createdAt) {
325	        jdbc.update("INSERT INTO idempotency_record (request_id, endpoint, fingerprint, response_status, "
326	                + "response_body, created_at) VALUES (?,?,?,-1,NULL,?)", requestId, endpoint, fingerprint,
327	                Timestamp.valueOf(createdAt));
328	    }
329	
330	    /**
331	     * 完成幂等记录，写入首次响应。
332	     */
333	    public void completeIdempotency(String requestId, int responseStatus, String responseBody) {
334	        jdbc.update("UPDATE idempotency_record SET response_status = ?, response_body = ? WHERE request_id = ?",
335	                responseStatus, responseBody, requestId);
336	    }
337	
338	    /**
339	     * 删除幂等记录（系统异常时允许重试）。
340	     */
341	    public void deleteIdempotency(String requestId) {
342	        jdbc.update("DELETE FROM idempotency_record WHERE request_id = ?", requestId);
343	    }
344	
345	    /**
346	     * 占用调合罐执行锁。唯一键冲突时抛出 DuplicateKeyException。
347	     */
348	    public void acquireTankLock(long blendTankId, long orderId, LocalDateTime createdAt) {
349	        jdbc.update("INSERT INTO blend_tank_lock (blend_tank_id, order_id, created_at) VALUES (?,?,?)",
350	                blendTankId, orderId, Timestamp.valueOf(createdAt));
351	    }
352	
353	    /**
354	     * 释放调合罐执行锁。
355	     */
356	    public void releaseTankLock(long blendTankId) {
357	        jdbc.update("DELETE FROM blend_tank_lock WHERE blend_tank_id = ?", blendTankId);
358	    }
359	
360	    private <T> Optional<T> queryOne(String sql, RowMapper<T> mapper, Object... args) {
361	        try {
362	            return Optional.ofNullable(jdbc.queryForObject(sql, mapper, args));
363	        } catch (EmptyResultDataAccessException e) {
364	            return Optional.empty();
365	        }
366	    }
367	}
