1	package com.example.starter.blend;
2	
3	import com.example.starter.blend.BlendDtos.ErrorBody;
4	import com.example.starter.blend.BlendRepository.IdemRecord;
5	import com.fasterxml.jackson.databind.ObjectMapper;
6	import org.springframework.dao.DuplicateKeyException;
7	import org.springframework.stereotype.Component;
8	import org.springframework.transaction.PlatformTransactionManager;
9	import org.springframework.transaction.support.TransactionTemplate;
10	
11	import java.nio.charset.StandardCharsets;
12	import java.security.MessageDigest;
13	import java.security.NoSuchAlgorithmException;
14	import java.time.Clock;
15	import java.time.LocalDateTime;
16	import java.util.HexFormat;
17	import java.util.function.Supplier;
18	
19	/**
20	 * 幂等执行器：指纹覆盖 requestId 与全部业务字段。
21	 * 同键同参返回首次结果；同键异参返回 409 且不执行业务、不占用罐量。
22	 * 幂等记录使用独立事务（REQUIRES_NEW）提交，业务异常结果同样落库，保证重放语义一致。
23	 */
24	@Component
25	public class IdempotencyExecutor {
26	
27	    private static final int STATUS_PROCESSING = -1;
28	
29	    private final BlendRepository repository;
30	    private final ObjectMapper objectMapper;
31	    private final Clock clock;
32	    private final TransactionTemplate requiresNew;
33	
34	    public IdempotencyExecutor(BlendRepository repository, ObjectMapper objectMapper, Clock clock,
35	                               PlatformTransactionManager transactionManager) {
36	        this.repository = repository;
37	        this.objectMapper = objectMapper;
38	        this.clock = clock;
39	        this.requiresNew = new TransactionTemplate(transactionManager);
40	        this.requiresNew.setPropagationBehaviorName("PROPAGATION_REQUIRES_NEW");
41	    }
42	
43	    /**
44	     * 在幂等保护下执行业务动作。
45	     *
46	     * @param endpoint    接口标识
47	     * @param requestId     幂等键
48	     * @param fingerprint 请求指纹（requestId + 全部业务字段）
49	     * @param bodyType    响应类型
50	     * @param action      业务动作
51	     * @return 首次执行结果或重放的首次结果
52	     */
53	    public <T> T execute(String endpoint, String requestId, String fingerprint,
54	                         Class<T> bodyType, Supplier<T> action) {
55	        if (!tryInsertPlaceholder(endpoint, requestId, fingerprint)) {
56	            return replay(requestId, fingerprint, bodyType);
57	        }
58	        try {
59	            T body = action.get();
60	            complete(requestId, 200, writeJson(body));
61	            return body;
62	        } catch (BlendException e) {
63	            complete(requestId, e.status(),
64	                    writeJson(new ErrorBody("BUSINESS_REJECTED", e.getMessage())));
65	            throw e;
66	        } catch (RuntimeException e) {
67	            // 系统异常不留幂等记录，允许调用方重试
68	            requiresNew.executeWithoutResult(s -> repository.deleteIdempotency(requestId));
69	            throw e;
70	        }
71	    }
72	
73	    /**
74	     * 计算请求指纹：SHA-256 覆盖 requestId 与全部业务字段的规范串。
75	     */
76	    public String fingerprint(String requestId, Object... businessFields) {
77	        StringBuilder canonical = new StringBuilder(requestId == null ? "" : requestId);
78	        for (Object field : businessFields) {
79	            canonical.append('|').append(field == null ? "null" : field.toString());
80	        }
81	        try {
82	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
83	            return HexFormat.of().formatHex(digest.digest(canonical.toString().getBytes(StandardCharsets.UTF_8)));
84	        } catch (NoSuchAlgorithmException e) {
85	            throw new IllegalStateException("SHA-256 不可用", e);
86	        }
87	    }
88	
89	    private boolean tryInsertPlaceholder(String endpoint, String requestId, String fingerprint) {
90	        return Boolean.TRUE.equals(requiresNew.execute(status -> {
91	            try {
92	                repository.insertIdempotency(requestId, endpoint, fingerprint, LocalDateTime.now(clock));
93	                return true;
94	            } catch (DuplicateKeyException e) {
95	                return false;
96	            }
97	        }));
98	    }
99	
100	    private <T> T replay(String requestId, String fingerprint, Class<T> bodyType) {
101	        IdemRecord record = repository.findIdempotency(requestId)
102	                .orElseThrow(() -> BlendException.conflict("幂等记录不存在，请重试"));
103	        if (!record.fingerprint().equals(fingerprint)) {
104	            throw BlendException.conflict("requestId已使用且业务参数不一致，拒绝执行");
105	        }
106	        if (record.responseStatus() == STATUS_PROCESSING) {
107	            throw BlendException.conflict("相同请求正在处理中，请稍后重试");
108	        }
109	        if (record.responseStatus() == 200) {
110	            try {
111	                return objectMapper.readValue(record.responseBody(), bodyType);
112	            } catch (Exception e) {
113	                throw new IllegalStateException("幂等响应反序列化失败", e);
114	            }
115	        }
116	        throw new BlendException(record.responseStatus(), extractMessage(record.responseBody()));
117	    }
118	
119	    private void complete(String requestId, int status, String body) {
120	        requiresNew.executeWithoutResult(s -> repository.completeIdempotency(requestId, status, body));
121	    }
122	
123	    private String writeJson(Object body) {
124	        try {
125	            return objectMapper.writeValueAsString(body);
126	        } catch (Exception e) {
127	            throw new IllegalStateException("幂等响应序列化失败", e);
128	        }
129	    }
130	
