15	import java.util.concurrent.TimeUnit;
16	import java.util.concurrent.atomic.AtomicInteger;
17	
18	import static org.junit.jupiter.api.Assertions.assertEquals;
19	import static org.junit.jupiter.api.Assertions.assertTrue;
20	
21	/**
22	 * 并发边界测试：同一调合罐并发下达唯一成功；同键并发重放只执行一次。
23	 */
24	@SpringBootTest(properties = "spring.datasource.url=jdbc:h2:mem:blend_test_concurrent;"
25	        + "MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1")
26	class BlendConcurrencyTest extends BlendServiceTestBase {
27	
28	    private static CreateOrderRequest order(String requestId, long blendTankId, long tankId, String volume) {
29	        return new CreateOrderRequest(requestId, "GAS92", blendTankId,
30	                List.of(new ComponentAmount(tankId, new BigDecimal(volume))));
31	    }
32	
33	    @Test
34	    void concurrentOrdersOnSameBlendTankOnlyOneSucceeds() throws Exception {
35	        int threads = 4;
36	        ExecutorService pool = Executors.newFixedThreadPool(threads);
37	        CountDownLatch ready = new CountDownLatch(threads);
38	        CountDownLatch go = new CountDownLatch(1);
39	        AtomicInteger success = new AtomicInteger();
40	        AtomicInteger conflict = new AtomicInteger();
41	        AtomicInteger other = new AtomicInteger();
42	        try {
43	            var futures = java.util.stream.IntStream.range(0, threads)
44	                    .mapToObj(i -> pool.submit(() -> {
45	                        ready.countDown();
46	                        try {
47	                            go.await(5, TimeUnit.SECONDS);
48	                            service.createOrder(order("R-CC-" + i, 1, 1, "50"));
49	                            success.incrementAndGet();
50	                        } catch (BlendException e) {
51	                            if (e.status() == 409) {
52	                                conflict.incrementAndGet();
53	                            } else {
54	                                other.incrementAndGet();
55	                            }
56	                        } catch (Exception e) {
57	                            other.incrementAndGet();
58	                        }
59	                    }))
60	                    .toList();
61	            assertTrue(ready.await(10, TimeUnit.SECONDS));
62	            go.countDown();
63	            for (Future<?> future : futures) {
64	                future.get(30, TimeUnit.SECONDS);
65	            }
66	        } finally {
67	            pool.shutdownNow();
68	        }
69	        // 并发下达唯一成功，其余均为409罐占用冲突
70	        assertEquals(1, success.get());
71	        assertEquals(threads - 1, conflict.get());
72	        assertEquals(0, other.get());
73	        // 最终数据一致：仅一张调合单、一条罐锁、库存只扣减一次
74	        assertEquals(1, countRows("blend_order"));
75	        assertEquals(1, countRows("blend_tank_lock"));
76	        assertEquals(new BigDecimal("950.000"), remaining(1));
77	    }
